//! Shared emoji dataset + fuzzy search — the single source of emoji
//! data in the toolkit. Both the [`EmojiPicker`](crate::widget::EmojiPicker)
//! widget and the opt-in `:shortcode:` completion on
//! [`TextInput`](crate::widget::TextInput) read from here, so no app
//! (nor the on-screen keyboard) re-implements an emoji table.
//!
//! GENERATED by scripts/gen_emoji.py — edit the table there, not this file.

use crate::search::fuzzy_score;

/// A top-level emoji category. `Recent` is not a data group — the picker
/// synthesises it from usage — so it is not part of [`Group::ALL`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Group {
    Smileys,
    People,
    Animals,
    Food,
    Travel,
    Activities,
    Objects,
    Symbols,
    Flags,
}

impl Group {
    /// Every data-backed category, in display order.
    pub const ALL: &'static [Group] = &[
        Group::Smileys, Group::People, Group::Animals, Group::Food, Group::Travel, Group::Activities, Group::Objects, Group::Symbols, Group::Flags,
    ];

    /// Human-readable section title (already i18n-neutral English).
    pub fn label(self) -> &'static str {
        match self {
            Group::Smileys => "Smileys",
            Group::People => "People",
            Group::Animals => "Animals & Nature",
            Group::Food => "Food & Drink",
            Group::Travel => "Travel & Places",
            Group::Activities => "Activities",
            Group::Objects => "Objects",
            Group::Symbols => "Symbols",
            Group::Flags => "Flags",
        }
    }

    /// A representative glyph used on the category tab strip.
    pub fn tab_glyph(self) -> &'static str {
        match self {
            Group::Smileys => "\u{1f600}",
            Group::People => "\u{1f44d}",
            Group::Animals => "\u{1f436}",
            Group::Food => "\u{1f354}",
            Group::Travel => "\u{2708}\u{fe0f}",
            Group::Activities => "\u{26bd}",
            Group::Objects => "\u{1f4a1}",
            Group::Symbols => "\u{2764}\u{fe0f}",
            Group::Flags => "\u{1f3c1}",
        }
    }
}

/// One emoji entry: the glyph, its canonical `:shortcode:` name, search
