/// Every emoji in `group`, in table order.
pub fn in_group(group: Group) -> impl Iterator<Item = &'static Emoji> {
    EMOJI.iter().filter(move |e| e.group == group)
}

/// The emoji whose canonical shortcode is exactly `code` (no `:`), if any.
/// Used by the `:shortcode:` auto-replace when the user types the closing
/// colon.
pub fn exact(code: &str) -> Option<&'static Emoji> {
    EMOJI.iter().find(|e| e.name == code)
}

/// Best fuzzy score for `query` against an emoji's shortcode (weighted
/// higher) or any of its keywords. `None` when nothing matches.
pub fn score(query: &str, e: &Emoji) -> Option<i32> {
    // A shortcode hit outranks a keyword hit at equal raw score.
    let mut best = fuzzy_score(query, e.name).map(|s| s + 6);
    for kw in e.keywords {
        if let Some(s) = fuzzy_score(query, kw) {
            best = Some(best.map_or(s, |b| b.max(s)));
        }
    }
    best
}

/// Fuzzy-search the whole dataset, best matches first, capped at `limit`.
/// An empty query returns nothing (callers show categories instead).
pub fn search(query: &str, limit: usize) -> Vec<&'static Emoji> {
    let q = query.trim();
    if q.is_empty() {
        return Vec::new();
    }
    let mut scored: Vec<(i32, usize, &'static Emoji)> = EMOJI
        .iter()
        .enumerate()
        .filter_map(|(i, e)| score(q, e).map(|s| (s, i, e)))
        .collect();
    // Highest score first; stable by table order on ties.
    scored.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    scored.into_iter().take(limit).map(|(_, _, e)| e).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn shortcodes_are_unique() {
        let mut seen = HashSet::new();
        for e in EMOJI {
            assert!(seen.insert(e.name), "duplicate shortcode: {}", e.name);
        }
    }

    #[test]
    fn every_group_has_entries() {
        for g in Group::ALL {
            assert!(in_group(*g).next().is_some(), "empty group: {:?}", g);
        }
    }

    #[test]
    fn search_filters_by_name_and_keyword() {
        // Name match.
        let r = search("smi", 20);
        assert!(r.iter().any(|e| e.name == "smile"), "':smi' should suggest :smile:");
        // Keyword match: 'lol' is a keyword of joy/laughing, not a shortcode.
        let r = search("lol", 20);
        assert!(r.iter().any(|e| e.name == "joy" || e.name == "laughing"),
            "'lol' keyword should surface a laughing face");
        // Empty query yields nothing (categories are shown instead).
        assert!(search("", 20).is_empty());
    }

    #[test]
    fn exact_shortcode_lookup() {
        assert_eq!(exact("fire").map(|e| e.ch), Some("\u{1f525}"));
        assert!(exact("definitely_not_an_emoji").is_none());
    }
}
